exercise.referenceSolution:
#include <stdio.h>
#include <string.h>

static int data[2000];
static int size = 0;

static void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}

static void push(int x) {
    int i = size++;
    data[i] = x;
    while (i > 0 && data[(i - 1) / 2] > data[i]) {
        swap(&data[(i - 1) / 2], &data[i]);
        i = (i - 1) / 2;
    }
}

static int pop(void) {
    int top = data[0];
    data[0] = data[--size];
    int i = 0;
    for (;;) {
        int smallest = i, l = 2 * i + 1, r = 2 * i + 2;
        if (l < size && data[l] < data[smallest]) {
            smallest = l;
        }
        if (r < size && data[r] < data[smallest]) {
            smallest = r;
        }
        if (smallest == i) {
            break;
        }
        swap(&data[i], &data[smallest]);
        i = smallest;
    }
    return top;
}

int main(void) {
    char command[8];
    while (scanf("%7s", command) == 1) {
        if (strcmp(command, "push") == 0) {
            int x;
            if (scanf("%d", &x) != 1) {
                break;
            }
            push(x);
        } else if (strcmp(command, "pop") == 0 || strcmp(command, "top") == 0) {
            if (size == 0) {
                printf("пусто\n");
            } else {
                printf("%d\n", command[0] == 'p' ? pop() : data[0]);
            }
        } else if (strcmp(command, "size") == 0) {
            printf("%d\n", size);
        }
    }
    return 0;
}

